  stringx();
  stringx(const char *, int = -1);
  stringx(const stringx &);
  ~stringx();
  const char *c_str() const;
  stringx operator +(const stringx &) const;
};

struct nglMesh;

class nglFixedString
{
public:
  char Name[32];
  nglFixedString(const char *Text)
  {
    Name[0] = 0;
    strncpy(Name, Text, sizeof(Name) - 1);
    strlwr(Name);
  }
};

nglMesh *nglGetFirstMeshInFile(const nglFixedString &);
void nglReleaseMeshFile(const nglFixedString &);

class entity
{
  char pad[112];
public:
  stringx fileName;
  virtual void unused00();
  virtual void set_mesh(nglMesh *);
  virtual void unused02();
  virtual void set_lores_mesh(nglMesh *);
};

class conglomerate : public entity
{
public:
  entity *get_member(const stringx &);
};

void BOARD_UnloadMesh(entity *board)
{
	if (!board)
		return;
  while (nglGetFirstMeshInFile((board->fileName + stringx("_lo")).c_str()))
	nglReleaseMeshFile((board->fileName + stringx("_lo")).c_str());

  ((conglomerate*)board)->get_member("BOARD")->set_lores_mesh((nglMesh *)0x0);


	  while (nglGetFirstMeshInFile((board->fileName).c_str()))
    nglReleaseMeshFile((board->fileName).c_str());
  ((conglomerate*)board)->get_member("BOARD")->set_mesh((nglMesh *)0x0);


}
